# ---------- 1. light theme: flip the dark purples / pale text, keep accents ----------
KEEP={(0x2A,0x16,0x00),(0x3A,0x1E,0x00)}
def flip(r,g,b):
    if (r,g,b) in KEEP: return None
    h,l,sat=colorsys.rgb_to_hls(r/255,g/255,b/255); hd=h*360
    if sat<.08: h,sat=275/360,.3
    purpleish = sat<.4 or 200<=hd<=300
    if l<.26:   # any very dark background -> light tint of the same hue
        nl=0.975-(l*0.30); ns=min(sat,.6)*.85
    elif not purpleish: return None
    elif l<.36:
        nl=0.975-(l*0.30); ns=min(sat,.55)*.9
    elif l>.72: # pale text -> deep plum ink
        nl=0.16+(1-l)*0.9; ns=min(.5,sat+.12)
    else:
        nl=max(.30,1-l-.08); ns=sat
    rr,gg,bb=colorsys.hls_to_rgb(h,nl,ns); return int(rr*255+.5),int(gg*255+.5),int(bb*255+.5)
def hexsub(m):
    pre,hx=m.group(1),m.group(2)
    if len(hx)==3: r,g,b=[int(c*2,16) for c in hx]
    else: r,g,b=int(hx[0:2],16),int(hx[2:4],16),int(hx[4:6],16)
    f=flip(r,g,b); return m.group(0) if not f else pre+'#%02X%02X%02X'%f
def rgbasub(m):
    r,g,b=int(m.group(1)),int(m.group(2)),int(m.group(3)); f=flip(r,g,b)
    if not f: return m.group(0)
    a=m.group(4)
    # dark scrims/shadows stay dark-ish but lighter; keep shadows as shadows
    if (r+g+b)<120 and a is not None: return m.group(0)
    return f'rgba({f[0]},{f[1]},{f[2]}{"," + a if a is not None else ""})'
